"""Writes keka/catalog.json. Local only."""
import json
M = "Verified on macOS 15.6.1 with Keka 1.6.0 only, so it isn't known to work on macOS 26 or any other version."
ROOT = "Only touches what KEKA_ALLOWED_ROOT allows if it is set; if it isn't set, any item you can reach is accepted."
EN = "It depends on English names and was tested only in English."
WIN = "It needs Keka's main window (the one with the Format pop-up); if it was closed, the command raises UIError."
UIM = {"name": "mode", "type": "str", "required": False, "default": "ui", "meaning": "Must be \"ui\": Keka's scripting hung in testing."}
V = {"name": "ValueError", "when": "an argument is invalid or mode isn't \"ui\" or \"background\""}
U = {"name": "UIError", "when": "a named element never appeared, or the change wasn't seen in time"}
S = {"name": "StateBlocked", "when": "Keka shows a dialog with typed text, or another app came to the front; nothing is changed"}
NS = {"name": "NotSupported", "when": "mode is \"background\": Keka's scripting hung in testing"}
PRE = "The program has Accessibility, and Automation for System Events."
FMT = {"name": "format", "type": "str", "required": True, "default": None, "meaning": "zip, tar, 7z, gzip, bzip2, xz, dmg or iso."}
def cmd(name, desc, args, req, eff, post, ret, errs, gaps):
    return {"name": name, "description": desc, "args": args, "modes": {"verified": ["ui"], "default": "ui"}, "example_requests": req, "effects": eff, "destructive": False, "precondition": PRE, "postcondition": post, "returns": ret, "errors": errs, "known_gaps": gaps}
cmds = [
 cmd("archive_set_format", "Chooses the format Keka makes archives in, with the Format pop-up in Keka's window.", [FMT, UIM], ["Make Keka use TAR", "Switch Keka to 7z", "Set the archive format to ZIP"], "idempotent", "Keka makes archives in that format until it's changed.", {"type": "object", "fields": ["format"]}, [V, U, S, NS], [M, EN, WIN, "Only zip, tar and 7z were chosen in testing, and only zip and tar archives were made."]),
 cmd("archive_format", "Returns the format Keka makes archives in, read from its window.", [UIM], ["Which format is Keka using?", "Is Keka set to ZIP?", "What archive type will Keka make?"], "read_only", "Nothing is changed.", {"type": "object", "fields": ["format"]}, [V, U, NS], [M, EN, WIN]),
 cmd("archive_create", "Makes an archive of items in the same folder in Keka's current format, saved next to them.", [{"name": "paths", "type": "list", "required": True, "default": None, "meaning": "Absolute paths (or starting with ~) of items in the same folder."}, UIM], ["Zip these two files with Keka", "Make a TAR of this folder", "Archive the reports with Keka"], "non_idempotent", "A new archive next to the items holds them; the items stay.", {"type": "object", "fields": ["name", "path", "format", "from"]}, [V, U, S, {"name": "NotFound", "when": "nothing is at a path; nothing is made"}, {"name": "AlreadyExists", "when": "Keka proposes a name that's taken; nothing is made"}, {"name": "OutsideAllowedRoot", "when": "KEKA_ALLOWED_ROOT is set and a path is outside it; nothing is done"}, {"name": "NotSupported", "when": "mode is \"background\", or Keka is closed or hidden; nothing is done"}], [M, ROOT, EN, WIN, "It raises NotSupported while Keka is closed or hidden, because items handed to it then were dropped in testing; open Keka first.", "The items are opened with Keka, which asks where to save because it has no access to the folder; the dialog is filled in by name.", "The archive's name is Keka's own: the item's name for one item, Archive for several, numbered if taken.", "Compression level, passwords and splitting are left as Keka has them; TAR is made uncompressed."]),
]
cmds.append(cmd("archive_extract", "Expands an archive next to itself: it is opened with Keka, and Keka's folder dialog is answered with the archive's own folder.", [{"name": "path", "type": "str", "required": True, "default": None, "meaning": "An absolute path (or starting with ~) to a .zip, .tar, .7z, .gz, .tgz, .bz2, .xz or .rar."}, UIM], ["Unzip this file with Keka", "Extract the TAR archive", "Open up this 7z"], "non_idempotent", "The archive's items are next to it; the archive stays.", {"type": "object", "fields": ["archive", "items"]}, [V, U, S, {"name": "NotFound", "when": "nothing is at the path; nothing is done"}, {"name": "OutsideAllowedRoot", "when": "KEKA_ALLOWED_ROOT is set and the path is outside it; nothing is done"}, {"name": "NotSupported", "when": "mode is \"background\", or Keka is closed or hidden; nothing is done"}], [M, ROOT, EN, "It raises NotSupported while Keka is closed or hidden, like archive_create; open Keka first.", "Keka asks for a folder to extract to only when it has none it may use there; the archive's own folder is chosen.", "Only zip and TAR were tested; where Keka puts a clashing name is its own choice."]))
json.dump({"app": "Keka", "import": "import keka", "macos_version": "15.6.1 (24G90)", "app_version": "1.6.0 (5638)", "commands": cmds}, open("../keka/catalog.json", "w"), indent=2, ensure_ascii=False); open("../keka/catalog.json", "a").write("\n"); print(len(cmds))
